
import type { MoneyValue } from './MoneyValue.js';

export type SubscriptionDeliveryOption = { "amount_money"?: MoneyValue; "availability": "available" | "unavailable" | "cannot_calculate" | (string & {}); /** True when this is the subscription's saved preferred delivery method, including when unavailable. */ "current": boolean; "delivery_method_id": string; "description"?: string; /** Reason the method cannot serve this subscription destination. Values can expand as delivery capabilities change. */ "failure_category"?: "dependency_failure" | "timeout" | "malformed_response" | "callback_transport_failure" | "callback_circuit_open" | "callback_result_invalid" | "callback_unavailable" | "pricing_failure" | "schedule_failure" | "option_lifetime_too_short" | "geography_failure" | "routing_failure" | "invalid_configuration" | "invalid_buyer_input" | "address_verification_failed" | "address_could_not_be_verified" | (string & {}); "name": string; "price_type": "fixed" | "quoted" | (string & {}); /** True when this method is offered, renewable, and currently serves the destination. */ "selectable": boolean; "type": "shipment" | "local_delivery" | (string & {}); /** Reason the method cannot serve this subscription destination. Values can expand as delivery capabilities change. */ "unavailable_reason"?: "destination_not_served" | "pickup_unavailable" | "no_window_available" | "eligibility_no_match" | "method_type_not_allowed" | "pricing_unavailable" | "inventory_unavailable" | (string & {}); };
